import { buildSchema, graphql } from "graphql";
const schema = buildSchema("type Query { title: String!, pages: Int! }");

const rootValue = { title: () => "Moon Trip", pages: () => 24 };
const result = await graphql({ schema, rootValue, source: "query Card($details: Boolean!) { title pages @include(if: $details) }", variableValues: { details: false } });
console.log(JSON.stringify(result.data));
